const slider=document.querySelector('#speed-range');if(slider){const output=document.querySelector('#speed');const buttons=[...document.querySelectorAll('[data-speed]')];function update(value){slider.value=value;output.value=Number(value).toFixed(2);buttons.forEach(button=>button.setAttribute('aria-pressed',String(Number(button.dataset.speed)===Number(value))));}slider.addEventListener('input',()=>update(slider.value));buttons.forEach(button=>button.addEventListener('click',()=>update(button.dataset.speed)));}